#include <iostream>
#include <string>

class Door
{
public:
    Door(std::string name) : name(name) {}
    void toggle() { open = !open; }
    std::string describe() const { return name + (open ? " is open" : " is shut"); }
private:
    std::string name;
    bool open = false;
};

int main()
{
    Door d("Gate");
    std::cout << d.describe() << "\n";
    d.toggle();
    std::cout << d.describe() << "\n";
    return 0;
}

