exercises.solution:
#include <string>

class Enemy
{
public:
    Enemy(std::string name, int health) : name(name), health(health), maxHealth(health) {}
    void takeDamage(int amount)
    {
        health -= amount;
        if (health < 0) health = 0;
    }
    void heal(int amount)
    {
        health += amount;
        if (health > maxHealth) health = maxHealth;
    }
    bool isDead() const { return health == 0; }
    std::string describe() const { return name + " (" + std::to_string(health) + " HP)"; }
private:
    std::string name;
    int health;
    int maxHealth;
};
